async function captureToolResult(args: string[]): Promise<void> {
  const separator = args.indexOf("--");
  if (separator < 0) fail("tool-result capture requires -- before the command");
  const options = args.slice(0, separator);
  const argv = args.slice(separator + 1);
  if (options.length !== 2 || options[0] !== "--producer") {
    fail("tool-result capture requires exactly --producer <test|build|git>");
  }
  const producer = options[1];
  if (producer !== "test" && producer !== "build" && producer !== "git") {
    fail("--producer must be one of test, build, git");
  }
  if (argv.length === 0) fail("tool-result capture requires a command after --");
  const sessionId = process.env.CODEX_SESSION_ID;
  if (!sessionId) fail("TOOL_RESULT_SESSION_MISSING: CODEX_SESSION_ID was not supplied by the host");
  const binding = await requireWorkContextBinding({ bindingId: bindingIdForSession("codex", sessionId) });
  const receipt = await captureCommandResult({ argv, producer, binding, cwd: process.cwd() });
  const rendered = `${JSON.stringify(receipt)}\n`;
  if (Buffer.byteLength(rendered) > TOOL_RESULT_MAX_INLINE_BYTES) {
    fail("TOOL_RESULT_RECEIPT_TOO_LARGE: capture receipt exceeded the inline contract");
  }
  process.stdout.write(rendered);
  p

rocess.exitCode = receipt.summary.exit_code;
}

function fail(message: string, exitCode = 1): never {
  console.error(message);
  process.exit(exitCode);
  throw new Error(message);
}

function isStringFlagKey(key: string): key is StringFlagKey {
  return stringFlagKeys.includes(key as StringFlagKey);
}

function parseFlags(args: string[]): Flags {
  const flags: Flags = { _: [] };
  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index];
    if (!arg.startsWith("--")) {
      flags._.push(arg);
      continue;
    }
    const key = arg.slice(2);
    if (key === "json" || key === "staleness") {
      flags[key] = true;
      continue;
    }
    if (!isStringFlagKey(key)) fail(`Unknown flag --${key}`);
    const value = args[index + 1];
    if (value === undefined || value.startsWith("--")) fail(`Missing value for --${key}`);
    flags[key] = value;
    index += 1;
  }
  return flags;
}

function requiredFlag(flags: Flags, key: keyof Flags): string {
  const value = flags[key];
  if (typeof value !== "string" || value.trim().length === 0) fail(`Missing required --${String(key)}`);
  return value;
}

function parseSkillInvocationOutcome(value: string | undefined): SkillInvocationOutcome {
  if (value === "used" || value === "missed" || value === "false_positive") return value;
  fail("--outcome must be one of used, missed, false_positive");
}

function parseBrainUsageEvent(value: string | undefined): BrainUsageEvent {
  if (BRAIN_USAGE_EVENTS.includes(value as BrainUsageEvent)) return value as BrainUsageEvent;
  fail(`--event must be one of ${BRAIN_USAGE_EVENTS.join(", ")}`);
}

function parseBrainUsageSeverity(value: string | undefined): BrainUsageSeverity | undefined {
  if (value === undefined) return undefined;
  if (BRAIN_USAGE_SEVERITIES.includes(value as BrainUsageSeverity)) return value as BrainUsageSeverity;
  fail(`--severity must be one of ${BRAIN_USAGE_SEVERITIES.join(", ")}`);
}

function parseCommaList(value: string | undefined): string[] | undefined {
  if (value === undefined) return undefined;
  const items = value
    .split(",")
    .map((item) => item.trim())
    .filter((item) => item.length > 0);
  return items.length === 0 ? undefined : items;
}

function parseNonNegativeIntegerFlag(value: string | undefined, name: string): number | undefined {
  if (value === undefined) return undefined;
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed < 0) fail(`--${name} must be a non-negative integer`);
  return parsed;
}

function parseLimit(value: string | undefined): number | undefined {
  return parseNonNegativeIntegerFlag(value, "limit");
}

function gitRoot(cwd: string): string {
  const result = spawnSync("git", ["rev-parse", "--show-toplevel"], {
    cwd,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "ignore"],
  });
  if (result.status === 0) return result.stdout.trim();
  return resolve(cwd);
}

function resolveWorkspace(options: WorkspaceOptions = {}): ContinuityPaths {
  const cwd = resolve(options.cwd ?? process.cwd());
  const root = gitRoot(cwd);
  const stateRoot = resolve(options.stateRoot ?? process.env.ANVIL_STATE_ROOT ?? join(root, ".anvil"));
  const workspace = gitWorkspaceRef(root);
  return deriveContinuityPaths({ stateRoot, workspace });
}

async function readStdin(): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of process.stdin) {
    chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk)));
  }
  return Buffer.concat(chunks).toString("utf8");
}

function codexAdditionalContext(
  hookEventName: "SessionStart" | "UserPromptSubmit",
  additionalContext: string,
): {
  continue: true;
  hookSpecificOutput: {
    hookEventName: "SessionStart" | "UserPromptSubmit";
    additionalContext: string;
  };
} {
  return {
    continue: true,
    hookSpecificOutput: {
      hookEventName,
      additionalContext,
    },
  };
}

function codexPreToolUseOutput(input:
  | { decision: "deny"; reason: string; updatedInput?: never }
  | { decision: "allow"; updatedInput: Record<string, unknown>; reason?: never }): {
  hookSpecificOutput: {
    hookEventName: "PreToolUse";
    permissionDecision: "allow" | "deny";
    permissionDecisionReason?: string;
    updatedInput?: Record<string, unknown>;
  };
} {
  return {
    hookSpecificOutput: {
      hookEventName: "PreToolUse",
      permissionDecision: input.decision,
      ...(input.reason ? { permissionDecisionReason: input.reason } : {}),
      ...(input.updatedInput ? { updatedInput: input.updatedInput } : {}),
    },
  };
}

function workContextBoundToolName(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  for (const name of WORK_CONTEXT_BOUND_TOOLS) {
    if (value === name || value.endsWith(`__${name}`)) return name;
  }
  return undefined;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

const DIRECT_CODEX_CONTEXT_HOOK_PATTERN =
  /(?:^|[\s|;&])(?:(?:node|tsx)\s+)?["']?(?:[^\s"'|;&]+\/)*anvil(?:\.ts)?["']?\s+codex\s+(?:context-hook|session-start-hook)(?=$|[\s|;&])/m;

function isDirectCodexContextHookProbe(toolName: unknown, toolInput: unknown): boolean {
  if (toolName !== "Bash" || !isRecord(toolInput)) return false;
  const command = toolInput.command;
  return typeof command === "string" && DIRECT_CODEX_CONTEXT_HOOK_PATTERN.test(command);
}

function stripCallerMutationAuthority(
  input: Record<string, unknown>,
  _toolName: string,
): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(input).filter(([key]) => !HOST_OWNED_ROUTING_FIELDS.has(key)),
  );
}

function optionalHookIdentifier(value: unknown): string | undefined {
  return typeof value === "string" && value.trim().length > 0 ? value.trim() : undefined;
}

async function tryRecordHookRejection(code: WorkContextError["code"], operation: string): Promise<void> {
  try {
    await recordWorkContextRejection({ code, operation, host: "codex_hook" });
  } catch {
    // Hook denial remains authoritative even if local rejection telemetry is unavailable.
  }
}

function withBootstrapPointer(additionalContext: string): string {
  return [
    additionalContext,
    "",
    "## Anvil MCP Bootstrap",
    "",
    "Anvil MCP exposes `anvil_session_bootstrap` for compact read-only routing/status when the agent needs current Continuity, Brain, or Loci next-call guidance.",
    "This pointer does not replace the continuity frame; current instructions, files, command output, tests, and live tool results remain authoritative.",
  ].join("\n");
}

function writeBrainDiagnostics(brain: Pick<BrainContextResult, "diagnostics"> | Pick<ContextEnvelope, "diagnostics">): void {
  for (const diagnostic of brain.diagnostics) {
    const message = diagnostic.message.replace(/\s+/g, " ").trim();
    const recovery = diagnostic.recovery.replace(/\s+/g, " ").trim();
    process.stderr.write(`[anvil brain context] ${diagnostic.code}: ${message} Recovery: ${recovery}\n`);
  }
}

function contextLifecycle(source: unknown): Exclude<ContextLifecycle, "prompt"> {
  return source === "resume" || source === "clear" || source === "compact" ? source : "session_start";
}

function telemetryBrainFromEnvelope(envelope: ContextEnvelope): BrainContextResult {
  return {
    status: envelope.status === "degraded" ? "degraded" : "ready",
    markdown: envelope.markdown,
    diagnostics: [...envelope.diagnostics],
    ...(envelope.receipt.project ? { matchedProject: envelope.receipt.project } : {}),
    selectedPages: [
      ...new Set(envelope.receipt.selectedEvidence.flatMap((evidence) => evidence.page ? [evidence.page] : [])),
    ],
    renderedBytes: envelope.receipt.budget.renderedBytes,
    hardBytes: envelope.receipt.budget.hardBytes,
    ...(envelope.receipt.snapshotDigest ? { snapshotDigest: envelope.receipt.snapshotDigest } : {}),
    ...(envelope.receipt.recallObservation !== null
      ? { recallObservation: envelope.receipt.recallObservation }
      : {}),
  };
}

const ANVIL_RETRIEVAL_FAILURE_CODES = new Set([
  "BRAIN_RETRIEVAL_FAILED",
  "BRAIN_RETRIEVAL_TIMEOUT",

  "BRAIN_RETRIEVAL_INVALID",
  "BRAIN_CONTEXT_BUDGET_VIOLATION",
]);

function isKernelEvidence(envelope: ContextEnvelope, evidence: ContextEnvelope["receipt"]["selectedEvidence"][number]): boolean {
  return envelope.receipt.kernel.action === "emitted" && evidence.id.startsWith("kernel:");
}

function promptRecallOutcomeFromEnvelope(envelope: ContextEnvelope) {
  const hasSupportingEvidence = envelope.receipt.selectedEvidence.some(
    (evidence) => !isKernelEvidence(envelope, evidence),
  );
  const hasRetrievalFailure =
    envelope.receipt.kernel.reason === "prompt_retrieval_degraded" ||
    envelope.diagnostics.some((diagnostic) => ANVIL_RETRIEVAL_FAILURE_CODES.has(diagnostic.code)) ||
    compilerHasUnavailableEvidence(envelope.receipt.compilerDiagnostics) ||
    envelope.receipt.stop.reason === "provider_degraded";
  return promptRecallEvent({
    status: envelope.status,
    hasSupportingEvidence,
    hasRetrievalFailure,
  });
}

async function tryRecordPromptRecallTelemetry(input: RecordPromptRecallTelemetryInput): Promise<void> {
  try {
    await recordPromptRecallTelemetry(input);
  } catch {
    process.stderr.write(
      "[anvil brain usage] BRAIN_USAGE_RECORD_FAILED: Automatic prompt recall telemetry could not be recorded. Recovery: Check the Brain usage state root and journal permissions.\n",
    );
  }
}

async function runContextHook(): Promise<void> {
  let input: CodexHookInput = {};
  const text = await readStdin();
  if (text.trim().length > 0) {
    try {
      input = JSON.parse(text);
    } catch {
      input = {};
    }
  }

  const cwd = typeof input.cwd === "string" && input.cwd.trim().length > 0 ? input.cwd : process.cwd();
  const hookEventName = input.hook_event_name ?? "SessionStart";
  if (hookEventName === "PreToolUse") {
    if (isDirectCodexContextHookProbe(input.tool_name, input.tool_input)) {
      const reason =
        "HOST_LIFECYCLE_PROBE_BLOCKED: Agent-issued Codex lifecycle-hook probes are forbidden. Use the context injected by the registered host hook.";
      process.stderr.write(`[anvil codex hook] ${reason}\n`);
      process.stdout.write(`${JSON.stringify(codexPreToolUseOutput({ decision: "deny", reason }))}\n`);
      return;
    }
    const toolName = workContextBoundToolName(input.tool_name);
    if (!toolName) {
      return;
    }
    if (!isRecord(input.tool_input)) {
      const reason = "WORK_CONTEXT_MISMATCH: Anvil mutation tool input must be an object";
      await tryRecordHookRejection("WORK_CONTEXT_MISMATCH", toolName);
      process.stderr.write(`[anvil work context] ${reason}\n`);
      process.stdout.write(`${JSON.stringify(codexPreToolUseOutput({ decision: "deny", reason }))}\n`);
      return;
    }
    try {
      const binding = await refreshCodexWorkContext({ cwd: input.cwd, sessionId: input.session_id });
      let trustedInput = stripCallerMutationAuthority(input.tool_input, toolName);
      if (toolName === "anvil_skill_invocation_log") {
        const {
          host: _callerHost,
          sessionId: _callerSessionId,
          turnId: _callerTurnId,
          messageId: _callerMessageId,
          ...skillInput
        } = trustedInput;
        const turnId = optionalHookIdentifier(input.turn_id);
        const messageId = optionalHookIdentifier(input.message_id);
        trustedInput = {
          ...skillInput,
          ...(turnId ? { turnId } : {}),
          ...(messageId ? { messageId } : {}),
        };
      }
      process.stdout.write(
        `${JSON.stringify(
          codexPreToolUseOutput({
            decision: "allow",
            updatedInput: { ...trustedInput, bindingId: binding.id },
          }),
        )}\n`,
      );
      return;
    } catch (error) {
      if (!(error instanceof WorkContextError)) throw error;
      await tryRecordHookRejection(error.code, toolName);
      writeWorkContextDiagnostic(error);
      const reason = `${error.code}: ${error.message}`;
      process.stdout.write(`${JSON.stringify(codexPreToolUseOutput({ decision: "deny", reason }))}\n`);
      return;
    }
  }
  if (hookEventName === "Stop") {
    if (input.stop_hook_active === true) return;

    let binding;
    try {
      binding = await requireCodexWorkContext({ cwd: input.cwd, sessionId: input.session_id });
    } catch (error) {
      if (!(error instanceof WorkContextError)) throw error;
      writeWorkContextDiagnostic(error);
      return;
    }

    const closure = await readBrainMaintenanceClosure({
      cwd: binding.collaboration_space.root,
      env: process.env,
      sessionId: binding.session_id,
    });
    if (closure.kind === "malformed") {
      const reason =
        `Brain maintenance closure cannot be verified because the usage journal is malformed: ${closure.message}`;
      process.stderr.write(`[anvil brain maintenance] ${reason}\n`);
      process.stdout.write(`${JSON.stringify({ decision: "block", reason })}\n`);
      return;
    }
    if (closure.kind === "ok" && closure.unresolved.length > 0) {
      const incidents = closure.unresolved
        .slice(0, 3)
        .map((record) => `${record.id} (${record.event}${record.pages?.[0] ? `: ${record.pages[0]}` : ""})`)
        .join(", ");
      const omitted = closure.unresolved.length - Math.min(closure.unresolved.length, 3);
      const reason = [
        `Brain maintenance is not closed for this session: ${incidents}${omitted > 0 ? `, plus ${omitted} more` : ""}.`,
        "Resolve each incident in this current main session before handoff: update, verify, and commit Brain, then record an updated event related to the incident ID; or record an evidence-backed not_needed event related to it when Steward review finds no Brain change is warranted.",
        "Do not launch a child agent, model, judge, deferred handoff, or maintenance queue.",
      ].join(" ");
      process.stdout.write(`${JSON.stringify({ decision: "block", reason })}\n`);
    }
    return;
  }
  if (hookEventName === "UserPromptSubmit") {
    let workContextDiagnostic = "";
    try {
      await requireCodexWorkContext({ cwd: input.cwd, sessionId: input.session_id });
    } catch (error) {
      if (!(error instanceof WorkContextError)) throw error;
      writeWorkContextDiagnostic(error);
      workContextDiagnostic = renderWorkContextDiagnostic(error);
    }
    if (process.env.ANVIL_BRAIN_CONTEXT === "off") {
      if (!workContextDiagnostic) {
        await tryRecordPromptRecallTelemetry({ cwd, lifecycle: input, event: "disabled" });
      }
      process.stdout.write(
        `${JSON.stringify(
          codexAdditionalContext("UserPromptSubmit", workContextDiagnostic),
        )}\n`,
      );
      return;
    }
    const startedAt = performance.now();
    const envelope = await planContext({
      lifecycle: "prompt",
      cwd,
      prompt: typeof input.prompt === "string" ? input.prompt : "",
      ...(input.temporal !== undefined ? { temporal: input.temporal } : {}),
      host: "codex",
      sessionId: optionalHookIdentifier(input.session_id),
      reservedBytes: Buffer.byteLength(workContextDiagnostic, "utf8"),
    });
    const telemetryBrain = telemetryBrainFromEnvelope(envelope);
    if (!workContextDiagnostic) {
      await tryRecordPromptRecallTelemetry({
        cwd,
        lifecycle: input,
        event: promptRecallOutcomeFromEnvelope(envelope),
        durationMs: Math.round(performance.now() - startedAt),
        brain: telemetryBrain,
      });
    }
    writeBrainDiagnostics(envelope);
    const promptContext = [envelope.markdown, workContextDiagnostic]
      .filter((value) => value.length > 0)
      .join("\n\n");
    process.stdout.write(`${JSON.stringify(codexAdditionalContext("UserPromptSubmit", promptContext))}\n`);
    return;
  }
  if (hookEventName !== "SessionStart") {
    fail("anvil codex context-hook supports only SessionStart, UserPromptSubmit, PreToolUse, and Stop hook events");
  }

  let binding;
  try {
    binding = await bindCodexWorkContext({
      cwd: input.cwd,
      sessionId: input.session_id,
      source: input.source,
    });
  } catch (error) {
    if (!(error instanceof WorkContextError)) throw error;
    writeWorkContextDiagnostic(error);
    proce

ss.stdout.write(
      `${JSON.stringify(codexAdditionalContext("SessionStart", renderWorkContextDiagnostic(error)))}\n`,
    );
    return;
  }

  const paths = resolveWorkspace({ cwd });
  const current = await readCurrent(paths);
  let additionalContext;
  if (current.kind === "ok") {
    additionalContext = renderContinuityFrame(current.value);
  } else if (current.kind === "missing") {
    additionalContext = [
      "## Anvil Continuity Frame",
      "",
      "No Anvil continuity frame is initialized for this workspace yet.",
      "",
      "Do not invent continuity. Use current user instruction, current files, and live project evidence as the source of truth.",
      `State root: ${paths.stateRoot}`,
      `Workspace: ${paths.workspace.label ?? paths.workspace.key} (${paths.workspace.root})`,
    ].join("\n");
  } else {
    additionalContext = renderMalformedContinuityDiagnostic({
      path: current.path,
      message: current.message,
      workspace_key: paths.workspace.key,
    });
  }

  const workContext = renderWorkContext(binding);
  additionalContext = `${workContext}\n\n${additionalContext}`;
  const compactAdditionalContext = [
    "## Anvil Work Context",
    "",
    `Binding: ${binding.id} (${binding.status})`,
    `Collaboration space: ${binding.collaboration_space.label ?? binding.collaboration_space.key}`,
    "",
    "## Anvil Continuity Active Task",
    "",
    ...(current.kind === "ok"
      ? renderActiveTask(current.value.active_task)
      : ["Active task:", "- unavailable because Continuity is not readable"]),
    "",
    "## Anvil Continuity Frame",
    "",
    "[truncated; read Continuity through Anvil when orientation is uncertain]",
  ].join("\n");

  if (process.env.ANVIL_BRAIN_CONTEXT === "off") {
    process.stdout.write(
      `${JSON.stringify(codexAdditionalContext("SessionStart", withBootstrapPointer(additionalContext)))}\n`,
    );
    return;
  }

  const envelope = await planContext({
    lifecycle: contextLifecycle(input.source),
    cwd,
    host: "codex",
    sessionId: optionalHookIdentifier(input.session_id),
    reservedBytes: Buffer.byteLength(additionalContext.trimEnd(), "utf8") + 2,
  });
  writeBrainDiagnostics(envelope);
  const context = renderSessionStartContext({
    continuity: additionalContext,
    compactContinuity: compactAdditionalContext,
    brain: envelope.markdown,
    hardBytes: envelope.receipt.budget.hardBytes,
  });
  if (context.truncated) {
    process.stderr.write(
      "[anvil brain context] BRAIN_CONTEXT_BUDGET_VIOLATION: Context Harness output exceeded the reviewed host envelope. Recovery: Inspect the Recall Receipt and repair the producer-to-envelope budget contract.\n",
    );
  }
  process.stdout.write(`${JSON.stringify(codexAdditionalContext("SessionStart", context.markdown))}\n`);
}

