  const current = await readCurrent(paths);
  if (flags.json) {
    process.stdout.write(`${JSON.stringify(current, null, 2)}\n`);
    return;
  }
  if (current.kind === "ok") {
    process.stdout.write(`${renderContinuityFrame(current.value)}\n`);
  } else if (current.kind === "missing") {
    process.stdout.write(`No Anvil continuity frame found at ${paths.currentPath}\n`);
  } else {
    process.stdout.write(
      `${renderMalformedContinuityDiagnostic({
        path: current.path,
        message: current.message,
        workspace_key: paths.workspace.key,
      })}\n`,
    );
  }
}

